    # versions themselves are checked by the safbox-tools-<n> controls.
    its('stdout') { should match(/^CINC Auditor:\s+\S/) }
    its('stdout') { should match(/^SAF CLI:\s+\S/) }
    its('stdout') { should match(/^Ansible core:\s+\S/) }
    its('stdout') { should match(/^Packer:\s+\S/) }
  end
end

control 'safbox-fips-1' do
  impact 1.0
  title 'FIPS mode is enabled and was set at install'
  desc 'ADR-0001: FIPS mode is on from installation and is not configurable afterward. The kernel must report fips_enabled=1 and fips=1 must be on the command line.'
  only_if('FIPS is not required for this image') { input('fips_required') }

  describe file('/proc/sys/crypto/fips_enabled') do
    it { should exist }
    its('content.strip') { should cmp '1' }
  end

  describe file('/proc/cmdline') do
    its('content') { should match(/(^|\s)fips=1(\s|$)/) }
  end
end

control 'safbox-fips-2' do
